        }catch(error){
          if(signal?.aborted)throw error;
          output={state:'UNAVAILABLE',bytes:null,sha256:null,originalState:'SAVED',
            code:typeof error.code==='string'&&/^[A-Z0-9_]{1,120}$/.test(error.code)?error.code:'RETAINED_OUTPUT_READ_FAILED'};
        }
